```c++
template <typename T>
constexpr T constexpr_add(T a, T b) {
  return a + b;
}

int main() {
  constexpr int x = 5;
  constexpr int y = 10;
  constexpr int sum = constexpr_add(x, y); // Compile-time evaluation
  int a = 15;
  int b = 20;
  int runtime_sum = constexpr_add(a, b); // Runtime evaluation (if a and b are not constexpr)
  std::cout << sum << " " << runtime_sum << std::endl; 
  return 0;
}```
